function* idGenerator(): Generator<number, void, unknown> {
  let id = 1;
  while (true) {
    yield id++;
  }
}

// Async Iterator for streaming data:
async function* streamNumbers(): AsyncGenerator<number> {
  yield 1;
  await new Promise(r => setTimeout(r, 100));
  yield 2;
}

// Consuming via for await..of:
